package az.achiqyol.exception;
import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import jakarta.validation.ConstraintViolationException; @RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(NotFoundException.class) public ProblemDetail missing(NotFoundException e) { return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND,e.getMessage()); } @ExceptionHandler({MethodArgumentNotValidException.class,ConstraintViolationException.class}) public ProblemDetail invalid(Exception e) { return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST,"Invalid input. Check names, coordinates and pagination limits."); } }
